package org.eclipse.rdf4j.sail.memory;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.Dataset;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQuery;
import org.eclipse.rdf4j.query.algebra.evaluation.EvaluationStrategy;
import org.eclipse.rdf4j.query.algebra.evaluation.TripleSource;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategy;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategyFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * A strategy subclass that has not adopted prepared query bindings may only be asked to prepare a query without
 * parameters. The repository API hands its own, empty parameter set to the Sail, which must count as no parameters.
 */
class MemoryUnadoptedEvaluationStrategyTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VF.createIRI("urn:s");
	private static final IRI PREDICATE = VF.createIRI("urn:p");

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		MemoryStore store = new MemoryStore();
		store.setEvaluationStrategyFactory(new DefaultEvaluationStrategyFactory() {
			@Override
			public EvaluationStrategy createEvaluationStrategy(Dataset dataset, TripleSource source,
					EvaluationStatistics statistics) {
				return new DefaultEvaluationStrategy(source, dataset, getFederatedServiceResolver(), 0, statistics) {
				};
			}
		});
		repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(SUBJECT, PREDICATE, VF.createLiteral("o"));
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void repositoryQueryWithoutParametersRuns() {
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery("SELECT ?s WHERE { ?s <urn:p> ?o }");
			assertThat(QueryResults.asList(query.evaluate())).extracting(row -> row.getValue("s"))
					.containsExactly(SUBJECT);
		}
	}

	@Test
	void repositoryQueryWithParametersStillFailsClosed() {
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery query = connection.prepareTupleQuery("SELECT ?s WHERE { ?s <urn:p> ?o }");
			query.setBinding("s", SUBJECT);
			assertThatThrownBy(() -> QueryResults.asList(query.evaluate()))
					.isInstanceOf(QueryEvaluationException.class)
					.hasStackTraceContaining("has not opted in to prepared query bindings");
		}
	}
}
